// 1. Get the raw output from the AI agent
let rawOutput = items[0].json.output;

// Clean up potential markdown formatting just in case the AI leaks code blocks
rawOutput = rawOutput.replace(/```json/g, '').replace(/```/g, '').trim();

// 2. Parse the AI decisions
const decisions = JSON.parse(rawOutput);

// 3. Get the main JSON from the preliminary data node
// Make sure 'Data_Fetcher' matches the EXACT name of your first JS node
const mainJson = $('Data_Fetcher').first().json;

// 4. Map decisions by type for safe lookup (now including logic)
const decisionMap = {};
decisions.forEach(d => {
  // Normalize to lowercase to ensure matching works flawlessly
  decisionMap[d.type.toLowerCase()] = {
    decision: d.decision.trim().toUpperCase(),
    logic: d.logic
  };
});

// 5. Apply classifications back onto the main json actuators
const updatedActuators = mainJson.actuators.map(a => {
  const aiData = decisionMap[a.type.toLowerCase()];

  if (!aiData) return a; // no decision found, leave untouched

  const decision = aiData.decision;
  const logic = aiData.logic;

  if (a.control_mode === 'auto') {
    return {
      ...a,
      classification: decision === 'TURN ON' ? 'TURN-ON' : 'KEEP-OFF'
    };
  }

  if (a.control_mode === 'semi-auto') {
    const status   = a.status.toLowerCase();
    const deciding = decision.toLowerCase(); // Use lower case for the logic block below

    let classification;
    if      (status === 'off' && deciding === 'turn on')  classification = 'TURN-ON';
    else if (status === 'on'  && deciding === 'turn off') classification = 'TURN-OFF';
    else if (status === 'off' && deciding === 'turn off') classification = 'KEEP-OFF';
    else if (status === 'on'  && deciding === 'turn on')  classification = 'KEEP-ON';
    else classification = a.classification; // fallback

    const updatedActuator = { ...a, classification };

    // Add recommended_action containing the logic for TURN-OFF actuators only
    if (classification === 'TURN-OFF') {
      updatedActuator.recommended_action = logic;
    }

    return updatedActuator;
  }

  return a; // fallback for unknown control mode
});

// 6. Return the updated JSON
return [{ json: { ...mainJson, actuators: updatedActuators } }];

const input = items[0].json;

// ─── Filter actuators first ───────────────────────────────────────────────────

// We now solely rely on the perfectly calculated `skipped` flag from Node 1.
const filteredActuators = (input.actuators ?? [])
  .filter(a => a.skipped === false)
  .map(a => ({
    type:           a.type,
    status:         a.status,
    control_mode:   a.control_mode,
    classification: a.classification
  }));

// ─── Stop if no actuators passed the filter ───────────────────────────────────

if (filteredActuators.length === 0) {
  // Return a debug payload so you can see why it's empty!
  return [{ 
    json: { 
      debug_warning: "ALL ACTUATORS WERE FILTERED OUT!",
      raw_input_actuators_were: input.actuators 
    } 
  }];
}

// ─── Filter & reshape ─────────────────────────────────────────────────────────

const output = {
  time: input.meta?.triggered_at ?? null,
  crop: input.crop ?? null, // ✅ FIXED: Replaced 'farm' with 'crop'
  sensors: (input.sensors ?? []).map(s => ({
    type:  s.type,          // ✅ FIXED: Uses 'type' instead of 'name'
    value: s.value
  })),
  actuators: filteredActuators
};

return [{ json: output }];
